import math

def perplexity(probs):
    nll = -sum(math.log(p) for p in probs) / len(probs)
    return math.exp(nll)

import math

def pass_at_k(n, c, k):
    if n - c < k:
        return 1.0
    return 1 - math.comb(n - c, k) / math.comb(n, k)

def pick(option_logprobs, normalize):
    scores = []
    for lp in option_logprobs:
        s = sum(lp)
        if normalize:
            s = s / len(lp)
        scores.append(s)
    return scores.index(max(scores))
